import csv
from datetime import datetime
def load_series(timeseries_id, start, end):
    with open(VALUES_CSV) as f:
        return [
            (datetime.fromisoformat(r['timestamp']), float(r['value']))
            for r in csv.DictReader(f)
            if r['timeseries_id'] == timeseries_id and
               start <= r['timestamp'] <= end
        ]
graph = {}
with open(GRAPH_TTL) as f:
    for line in f:
        subject, _, object = line.strip().partition(' ')
        graph.setdefault(subject, []).append(object)

with open(CATALOG_CSV) as f:
    catalog = list(csv.DictReader(f))
for p, l in zip(graph['?zone'], graph['?temperature'], graph['?setpoint']):
    for catp in catalog:
        if p == catp['point_uri']:
            ts_id = catp['timeseries_id']
            break
    temp_data = load_series(ts_id, '2018-07-07 10:00', '2018-07-07 10:00')
    for cats in catalog:
        if l == cats['point_uri']:
            ts_id = cats['timeseries_id']
            break
    sp_data = load_series(ts_id, '2018-07-07 10:00', '2018-07-07 10:00')
    value = temp_data[0][1] - sp_data[0][1]
print(value)
